// NOTE: Word-by-word text reveal animation
'use client';

import { useRef } from 'react';

import { motion, useInView } from 'motion/react';

import {
  wordRevealContainerVariants,
  wordRevealChildVariants,
} from '@/lib/animation-config';

interface WordRevealProps {
  /** The text to animate word-by-word */
  text: string;
  /** HTML element to render as — defaults to span */
  as?: 'h1' | 'h2' | 'h3' | 'h4' | 'p' | 'span';
  /** Additional className applied to the container */
  className?: string;
  /** Only animate once when entering viewport */
  once?: boolean;
  /** Amount of element visible before triggering (0-1) */
  amount?: number;
  /** Trigger on page load instead of scroll */
  onLoad?: boolean;
}

export function WordReveal({
  text,
  as: Tag = 'span',
  className,
  once = true,
  amount = 0.5,
  onLoad = false,
}: Readonly<WordRevealProps>) {
  const ref = useRef(null);
  const isInView = useInView(ref, { once, amount });

  const words = text.split(' ');

  return (
    <Tag className={className} ref={ref}>
      <motion.span
        initial="hidden"
        animate={onLoad || isInView ? 'visible' : 'hidden'}
        variants={wordRevealContainerVariants}
        className="inline"
      >
        {words.map((word, i) => (
          <motion.span
            key={`${word}-${i}`}
            variants={wordRevealChildVariants}
            className="inline-block"
          >
            {word}
            {/* NOTE: Preserve spaces between words */}
            {i < words.length - 1 && '\u00A0'}
          </motion.span>
        ))}
      </motion.span>
    </Tag>
  );
}
